// Lexicon render test (pipeline/DESIGN.md 7) on REAL entries: the golden
// src-tauri/tests/golden/lexicon-entries.json is machine-generated by the Rust
// core from pipeline/out/content.sqlite through open_verified (each entry is
// exactly what get_strongs returns). No lexicon text is typed here.
//
// For every golden entry the drawn panel must show:
// - each stored text node exactly (a `.lt` span per node, in document order),
//   omitting only whitespace-only nodes that are direct children of <entry>
//   (layout: OSHB CRLF + TAB indentation, MGNT spaces/line feeds);
// - display attributes with their stored values (`.la`);
// - every cross-reference (w@src, strongsref) as a button that opens its key;
// - no other characters, except UI labels.
import { describe, expect, it } from "vitest";
import { flushSync, mount, unmount } from "svelte";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import LexEntryView from "../src/components/LexEntryView.svelte";
import StudyPanel from "../src/components/StudyPanel.svelte";
import { LEXICON_CREDITS } from "../src/lib/attributions";
import { isLayoutWhitespace } from "../src/lib/lexicon";
import type { LexEntry, Lookup } from "../src/lib/types";

interface Golden { entries: { why: string; entry: LexEntry }[] }
const golden: Golden = JSON.parse(
  readFileSync(resolve(process.cwd(), "src-tauri/tests/golden/lexicon-entries.json"), "utf8"),
);
const byKey = (k: string) => golden.entries.find((e) => e.entry.key === k)!.entry;

function draw(entry: LexEntry, onRef: (k: string) => void = () => {}) {
  document.body.innerHTML = '<div id="t"></div>';
  const target = document.getElementById("t")!;
  const c = mount(LexEntryView, { target, props: { entry, onRef } });
  flushSync();
  return { root: target.querySelector<HTMLElement>("section.lex-entry")!, done: () => unmount(c) };
}

function textNodes(root: Node): Text[] {
  const out: Text[] = [];
  const w = document.createTreeWalker(root, 4 /* NodeFilter.SHOW_TEXT */);
  for (let n = w.nextNode(); n; n = w.nextNode()) out.push(n as Text);
  return out;
}

describe("lexicon entries render exactly as stored (real golden)", () => {
  it("the golden covers the expected shapes", () => {
    const keys = golden.entries.map((e) => e.entry.key);
    for (const k of ["H430", "H3068", "G26", "G2316"]) expect(keys).toContain(k);
    const texts = golden.entries.flatMap((e) => e.entry.nodes.map((n) => n.text ?? ""));
    expect(texts.some((t) => t.includes("\r\n\t"))).toBe(true); // OSHB layout (CRLF + TAB)
    expect(texts.some((t) => t.includes("\n") && !isLayoutWhitespace(t))).toBe(true); // LF inside a field
  });

  for (const { why, entry } of golden.entries) {
    it(`${entry.key} (${why})`, () => {
      const refs: string[] = [];
      const { root, done } = draw(entry, (k) => refs.push(k));

      // 1. stored text nodes, exactly, in document order
      const lt = [...root.querySelectorAll<HTMLElement>(".lt")];
      const drawn = lt.map((el) => Number(el.dataset.n));
      for (let i = 1; i < drawn.length; i++) expect(drawn[i]).toBeGreaterThan(drawn[i - 1]);
      for (const el of lt) {
        const node = entry.nodes[Number(el.dataset.n)];
        expect(node.text).not.toBeNull();
        expect(el.textContent).toBe(node.text);
        expect(el.childNodes.length).toBe(1); // one text node, no markup inside
      }
      // 2. only layout whitespace directly in <entry> is left out
      for (const n of entry.nodes) {
        if (n.text === null || drawn.includes(n.n)) continue;
        expect(n.parent, `node ${n.n} omitted`).toBeNull();
        expect(isLayoutWhitespace(n.text), `node ${n.n} omitted`).toBe(true);
      }
      expect(entry.nodes.some((n) => n.text !== null && !drawn.includes(n.n) && n.parent !== null)).toBe(false);

      // 3. display attributes show their stored values
      for (const el of root.querySelectorAll<HTMLElement>(".la")) {
        const owner = el.parentElement!.closest<HTMLElement>("[data-n]")!;
        const node = entry.nodes[Number(owner.dataset.n)];
        const a = node.attrs.find((x) => x.name === el.dataset.attr)!;
        expect(el.textContent).toBe(a.value);
      }
      // greek@unicode / translit and pronunciation@strongs are shown when present
      for (const n of entry.nodes) {
        for (const a of n.attrs) {
          if (["unicode", "translit"].includes(a.name) && n.name === "greek" || a.name === "strongs" && n.name === "pronunciation") {
            const el = root.querySelector<HTMLElement>(`[data-n="${n.n}"] > .la[data-attr="${a.name}"]`);
            expect(el?.textContent).toBe(a.value);
          }
        }
      }

      // 4. every cross-reference is a button that opens its key
      const withRef = entry.nodes.filter((n) => n.attrs.some((a) => a.ref_key));
      const buttons = [...root.querySelectorAll<HTMLButtonElement>("button.lex-ref")];
      expect(buttons.map((b) => Number(b.dataset.n))).toEqual(withRef.map((n) => n.n));
      for (const [i, b] of buttons.entries()) {
        const key = withRef[i].attrs.find((a) => a.ref_key)!.ref_key!;
        expect(b.dataset.ref).toBe(key);
        const lb = b.querySelector(".lb");
        if (lb) expect(lb.textContent).toBe(key); // empty element: shows its key (UI text)
        b.click();
      }
      expect(refs).toEqual(withRef.map((n) => n.attrs.find((a) => a.ref_key)!.ref_key));

      // 5. no other characters: every text node is stored text, a stored
      //    attribute value, a built key, or a UI label; whitespace-only text
      //    may sit only between blocks
      for (const t of textNodes(root)) {
        if (t.data === "") continue; // Svelte's empty anchor nodes draw nothing
        const p = t.parentElement!;
        if (p.closest(".lt, .la, .lb, .lex-label, .lex-key, .lex-src")) continue;
        expect(isLayoutWhitespace(t.data), `stray text ${JSON.stringify(t.data)}`).toBe(true);
        expect(p.matches("section.lex-entry, .lex-field"), `whitespace inside ${p.className}`).toBe(true);
      }
      // element nodes appear in document order too
      const els = [...root.querySelectorAll<HTMLElement>(".lex-el[data-n], .lex-ref[data-n]")].map((e) => Number(e.dataset.n));
      for (let i = 1; i < els.length; i++) expect(els[i]).toBeGreaterThan(els[i - 1]);
      done();
    });
  }
});

describe("study panel", () => {
  function panel(lookup: Lookup, onRef: (k: string, from: string) => void = () => {}) {
    document.body.innerHTML = '<div id="t"></div>';
    const c = mount(StudyPanel, {
      target: document.getElementById("t")!,
      props: {
        lookup, widthPx: 352, minPx: 288, maxPx: 640,
        onClose: () => {}, onResize: () => {}, onReset: () => {}, onRef,
      },
    });
    flushSync();
    return { root: document.getElementById("p-study")!, done: () => unmount(c) };
  }

  it("shows each key of a multi-key word, then each lexicon's required attribution", () => {
    const keys = ["G3588", "G2316", "H430"];
    const { root, done } = panel({
      kind: "done", title: "Lexicon for “x”", keys,
      results: keys.map((k) => ({ status: "ok" as const, entry: byKey(k) })),
    });
    expect([...root.querySelectorAll<HTMLElement>("section.lex-entry")].map((s) => s.dataset.key)).toEqual(keys);
    const credits = [...root.querySelectorAll("footer.lex-credit")].map((f) => [...f.querySelectorAll("p")].map((p) => p.textContent));
    expect(credits).toEqual([LEXICON_CREDITS["LEX-GRC-MGNT19"].paragraphs, LEXICON_CREDITS["LEX-HEB-OSHB"].paragraphs]);
    done();
  });

  it("a cross-reference reports the key and the entry it came from", () => {
    const calls: [string, string][] = [];
    const { root, done } = panel(
      { kind: "done", title: "t", keys: ["G26"], results: [{ status: "ok", entry: byKey("G26") }] },
      (k, from) => calls.push([k, from]),
    );
    const b = root.querySelector<HTMLButtonElement>("button.lex-ref")!;
    b.click();
    expect(calls).toEqual([[b.dataset.ref!, "G26"]]);
    done();
  });

  it("an unavailable lexicon says so, with the reason, and no entry text", () => {
    const reason = "content.sqlite: failed its checksum (damaged or replaced)";
    const { root, done } = panel({
      kind: "done", title: "t", keys: ["H430", "G26"],
      results: [{ status: "not_available", reason }, { status: "not_available", reason }],
    });
    expect(root.querySelectorAll("section.lex-entry").length).toBe(2);
    expect(root.querySelectorAll(".lt").length).toBe(0);
    expect(root.textContent).toContain("The lexicon is unavailable");
    expect(root.textContent).toContain("The Bible text is not affected");
    expect(root.querySelectorAll(".lex-msg.detail")[0].textContent).toBe(`Details: ${reason}`);
    expect(root.querySelectorAll("footer.lex-credit").length).toBe(0);
    done();
  });
});
